// Code node "Leads to rows". One row per business, with the verified email and the drafted opener.
// Shared helper: adds up what the agent's looot calls cost, from the agent's intermediate steps
// (the agent's "Return Intermediate Steps" option is on). Each looot tool answer carries actualCost.
function agentCost(item) {
  const steps = (item && Array.isArray(item.intermediateSteps)) ? item.intermediateSteps : [];
  let usd = 0;
  let calls = 0;
  for (const step of steps) {
    const tool = String((step && step.action && step.action.tool) || "");
    if (!/looot/i.test(tool)) continue;
    calls += 1;
    const text = typeof step.observation === "string" ? step.observation : JSON.stringify(step.observation ?? "");
    for (const m of text.matchAll(/"actualCost"\s*:\s*([0-9.eE+-]+)/g)) {
      const n = Number(m[1]);
      if (Number.isFinite(n)) usd += n;
    }
  }
  return { looot_calls: calls, looot_cost_usd: Number(usd.toFixed(6)) };
}

const item = $input.first().json;
const form = $("Lead search form").first().json;
const leads = (item.output && Array.isArray(item.output.leads)) ? item.output.leads : [];
const cost = agentCost(item);
const foundAt = new Date().toISOString();
return leads.filter((l) => l && l.name).map((l) => ({
  json: {
    name: String(l.name),
    address: l.address || "",
    phone: l.phone || "",
    website: l.website || "",
    email: String(l.email || "").toLowerCase(),
    email_status: l.email ? (l.email_status || "unknown") : "not_found",
    website_notes: l.website_notes || "",
    opener: l.opener || "",
    search: `${form["Business type"] || ""} in ${form["City or area"] || ""}`.trim(),
    found_at: foundAt,
    run_cost_usd: cost.looot_cost_usd,
  },
}));
